#include "telemetry.h"

#include <math.h>
#include <Arduino.h>

/* 1 — values are generated by the simulator, 0 — placeholder for the real link */
#ifndef C2_SIMULATE
#define C2_SIMULATE 1
#endif

/* 14S pack: 42.0 V empty, 58.8 V full */
#define PACK_EMPTY_V 42.0f
#define PACK_FULL_V  58.8f

telemetry_t telem = {
    .voltage_v = 58.2f,
    .batt_pct = 95,
    .rf_on = true,
    .wifi_on = true,
    .starlink_on = true,
    .lte_on = false,
    .vpn_on = true,
    .sats = 14,
    .odometer_km = 634,
    .uptime_ms = 0,
};

void telemetry_update(void)
{
    telem.uptime_ms = millis();
    float t = telem.uptime_ms / 1000.0f;

#if C2_SIMULATE
    /* Demo discharge, 70 s per cycle:
     *   0..20 s  95 -> 45 %   (green ring)
     *  20..40 s  45 -> 15 %   (green -> amber)
     *  40..60 s  15 ->  5 %   (amber -> red, last part below 10 % -> blinking)
     *  60..70 s   5 % hold    (blinking continues, easy to catch) */
    float cycle = fmodf(t, 70.0f);
    float pct;
    if (cycle < 20.0f) {
        pct = 95.0f - (95.0f - 45.0f) * (cycle / 20.0f);
    } else if (cycle < 40.0f) {
        pct = 45.0f - (45.0f - 15.0f) * ((cycle - 20.0f) / 20.0f);
    } else if (cycle < 60.0f) {
        pct = 15.0f - (15.0f - 5.0f) * ((cycle - 40.0f) / 20.0f);
    } else {
        pct = 5.0f;
    }

    telem.batt_pct = (uint8_t)(pct + 0.5f);
    telem.voltage_v = PACK_EMPTY_V + (pct / 100.0f) * (PACK_FULL_V - PACK_EMPTY_V);

    /* Links blink slowly, so both states are visible in the demo */
    telem.rf_on = true;
    telem.wifi_on = fmodf(t, 24.0f) < 15.0f;
    telem.starlink_on = fmodf(t, 36.0f) < 26.0f;
    telem.lte_on = fmodf(t, 48.0f) < 18.0f;
    telem.vpn_on = true;

    telem.sats = (telem.batt_pct > 0) ? (uint8_t)(12 + (int)(4.0f * sinf(t * 0.2f))) : 0;

    /* Odometer: starts at 634 km and grows by 1 km every 30 s so the digits
     * visibly change during a demo session. */
    telem.odometer_km = 634u + (uint32_t)(t / 30.0f);
#else
    (void)t;
#endif
}
